def transform(grid):
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])
    counts = {}
    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1

    bg = max(counts, key=counts.get)

    visited = set()
    queue = []

    # Add border background cells
    for c in range(W):
        if grid[0][c] == bg:
            visited.add((0, c))
            queue.append((0, c))
        if grid[H-1][c] == bg:
            visited.add((H-1, c))
            queue.append((H-1, c))

    for r in range(H):
        if grid[r][0] == bg:
            visited.add((r, 0))
            queue.append((r, 0))
        if grid[r][W-1] == bg:
            visited.add((r, W-1))
            queue.append((r, W-1))

    # BFS traversal using a simple list as queue
    idx = 0
    while idx < len(queue):
        r, c = queue[idx]
        idx += 1
        neighbors = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for dr, dc in neighbors:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if grid[nr][nc] == bg and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    # Fill enclosed background regions
    for r in range(H):
        for c in range(W):
            if grid[r][c] == bg and (r, c) not in visited:
                grid[r][c] = 4

    return grid
